def check_hierarchy_coherence(store_forecasts, regional_forecast, tol=1e-3):
    store_sum = sum(store_forecasts)
    diff_pct = abs(store_sum - regional_forecast) / max(regional_forecast, 1.0)
    return {'coherent': diff_pct <= tol, 'gap_pct': round(diff_pct * 100, 2)}

def pinball_loss(y_true, y_pred, quantile):
    err = y_true - y_pred
    return max(quantile * err, (quantile - 1.0) * err)

def compute_reorder_point(avg_daily_demand, std_demand, avg_lead_days, std_lead_days, z=1.65):
    # z=1.65 corresponds to ~95% cycle service level
    lead_demand = avg_daily_demand * avg_lead_days
    safety_stock = z * math.sqrt(avg_lead_days * (std_demand ** 2) + (avg_daily_demand ** 2) * (std_lead_days ** 2))
    return round(lead_demand + safety_stock, 1)

def uncensor_stockout_day(observed_sales, eod_inventory, rolling_in_stock_avg):
    if eod_inventory == 0 and observed_sales < rolling_in_stock_avg:
        return max(observed_sales, round(rolling_in_stock_avg, 1))
    return observed_sales
